2|//! Names are human-facing; the creation journal is not a lifecycle authority.
3|//! No retry ever repeats POST.
4|use anyhow::{Context, Result, ensure};
5|use op_cozo_store::{NativeCreationRecord, NativeCreationRequest};
6|use op_plugins::state_plugins::incus::{self, IncusRootRepairBackend};
7|use serde_json::{Value, json};
8|use sha2::{Digest, Sha256};
9|use crate::mutation_engine::MutationEngine;
10|
11|pub(crate) async fn records(engine: &MutationEngine) -> Result<Vec<NativeCreationRecord>> {
12|    let cozo = engine.identity_sled_store()?.cozo().clone();
13|    Ok(tokio::task::spawn_blocking(move || cozo.native_creation_records()).await??)
14|}
15|
16|pub(crate) fn request(operation: &str, actor: &str, session: &str, genesis: &str,
17|    kind: &str, target: &str, body: Value) -> Result<NativeCreationRequest> {
18|    ensure!(body.is_object() && body.get("name").is_none(), "native name is server assigned");
19|    let plugin = match kind { "identity" => "identity_sled", "project" => "project", "incus" => "incus",
20|        _ => anyhow::bail!("unknown native owner") };
21|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
22|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
23|    let request_json = serde_json::to_string(&body)?;
24|    let request_digest = format!("{:x}", Sha256::digest(request_json.as_bytes()));
25|    Ok(NativeCreationRequest { operation_id: operation.into(), actor_id: actor.into(),
26|        caller_session: session.into(), caller_genesis: genesis.into(), owner_kind: kind.into(),
27|        logical_target: target.into(), schema_hash: pin.schema_hash, request_digest, request_json,
28|        reserved_name: None })
29|}
30|
31|async fn admit(engine: &MutationEngine, request: &NativeCreationRequest) -> Result<()> {
32|    if let Some(name) = &request.reserved_name {
33|        let body: Value = serde_json::from_str(&request.request_json)?;
34|        let key = crate::identity_sled_dispatch::configured_chatbot_key()
35|            .context("reserved chatbot key is not configured")?;
36|        ensure!(name == "3tchedCtlChatbot" && request.owner_kind == "identity"
37|            && request.logical_target == op_identity::session::derive_session_id(&key)
38|            && crate::identity_sled_dispatch::control_plane_chatbot_session_id().as_deref()
39|                == Some(request.logical_target.as_str())
40|            && body["config"]["user.opdbus.session_id"] == request.logical_target
41|            && body["config"]["user.opdbus.wireguard_public_key"] == key,
42|            "reserved native name requires the configured chatbot binding");
43|    }
44|    let (plugin, method, capability) = match request.owner_kind.as_str() {
45|        "identity" => ("identity_sled", "prepare_container", "identity_sled.write"),
46|        "project" => ("project", "create", "project.create"),
47|        "incus" => ("incus", "create_instance", "cap.service.incus.instance.create@v1"),
48|        _ => anyhow::bail!("unknown native owner"),
49|    };
50|    crate::method_contract_admission::admit_compiled_method(plugin, method, Some(capability))?;
51|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
52|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
53|    ensure!(pin.schema_hash == request.schema_hash, "native creation seal changed; explicit reconciliation required");
54|    ensure!(crate::interceptor::load_capability_grants(&request.actor_id).contains(capability),
55|        "native creation requires current exact-principal grant");
56|    let current = engine.session_context_for_actor(&request.actor_id).await
57|        .context("native creation caller session missing")?;
58|    ensure!(current.session_id == request.caller_session && current.genesis_hex == request.caller_genesis,
59|        "native creation caller session changed");
60|    Ok(())
61|}
62|
63|/// Caller holds lifecycle (if applicable), then host observation lock. The
64|/// durable intent is committed and flushed before the sole POST permission.
65|pub(crate) async fn create_locked(engine: &MutationEngine, request: NativeCreationRequest)
66|    -> Result<(NativeCreationRecord, bool)> {
67|    admit(engine, &request).await?;
68|    let native = IncusRootRepairBackend::local();
69|    let before = native.default_project_state().await?;
70|    if request.owner_kind == "project" {
71|        let prior = records(engine).await?;
72|        ensure!(!before.instances.iter().any(|i|
73|            (i.name == request.logical_target || i.config.as_ref().is_some_and(|c|
74|                c.get("user.opdbus.project_id") == Some(&request.logical_target)))
75|            && !prior.iter().any(|r| r.name == i.name && r.request.operation_id == request.operation_id)),
76|            "existing project native binding must not be recreated");
77|    }
78|    let names = before.instances.iter().map(|i| i.name.clone()).collect::<Vec<_>>();
79|    let cozo = engine.identity_sled_store()?.cozo().clone();
80|    let (record, fresh) = tokio::task::spawn_blocking(move || cozo.reserve_native_creation(request, &names)).await??;
81|    // Any failure from here retains the fence, including definite provider
82|    // errors. An absent object is not proof that an earlier POST was rejected.
83|    if fresh {
84|        admit(engine, &record.request).await?;
85|        let mut body: Value = serde_json::from_str(&record.request.request_json)?;
86|        body["name"] = record.name.clone().into();
87|        body["config"]["user.opdbus.creation_operation"] = record.request.operation_id.clone().into();
88|        body["config"]["user.opdbus.creation_digest"] = record.request.request_digest.clone().into();
89|        incus::create_reserved_native(&body).await
90|            .context("native POST outcome requires reconciliation; reservation retained")?;
91|    }
92|    let record = reconcile_locked(engine, record).await?;
93|    Ok((record, !fresh))
94|}
95|
96|pub(crate) async fn reconcile_locked(engine: &MutationEngine, record: NativeCreationRecord)
97|    -> Result<NativeCreationRecord> {
98|    admit(engine, &record.request).await?;
99|    let native = IncusRootRepairBackend::local();
100|    let (raw, _) = native.instance(&record.name).await
101|        .context("reserved native instance absent or unreadable; POST will not be repeated")?;
102|    let body: Value = serde_json::from_str(&record.request.request_json)?;
103|    ensure!(raw["name"] == record.name && raw["type"] == body["type"]
104|        && raw["config"]["user.opdbus.creation_operation"] == record.request.operation_id
105|        && raw["config"]["user.opdbus.creation_digest"] == record.request.request_digest,
106|        "native creation ownership markers differ");
107|    if record.phase != "complete" {
108|        ensure!(raw["status"] == "Stopped" && raw["status_code"] == 102
109|            && raw["profiles"] == body["profiles"] && raw["devices"] == body["devices"],
110|            "native preparation is not the pinned stopped definition");
111|        if record.request.owner_kind == "identity" {
112|            ensure!(raw["expanded_config"]["security.privileged"] == "false"
113|                && raw["expanded_config"]["security.nesting"] == "false"
114|                && raw["expanded_config"]["boot.autostart"] == "false"
115|                && raw["expanded_config"]["raw.lxc"] == body["config"]["raw.lxc"],
116|                "expanded native identity security differs");
117|            let expanded = raw["expanded_devices"].as_object().context("expanded devices absent")?;
118|            ensure!(expanded.len() == 4 && expanded.get("root") == body["devices"].get("root")
119|                && expanded.get("runtime-run") == body["devices"].get("runtime-run")
120|                && expanded.get("fuse") == body["devices"].get("fuse")
121|                && expanded.get("lungs-socket-dir") == Some(&json!({"type":"disk", "source":"/run/opdbus/lungs",
122|                    "path":"/run/opdbus/lungs", "readonly":"true"})), "expanded identity devices differ");
123|        }
124|        for (key, value) in body["config"].as_object().context("creation config missing")? {
125|            ensure!(raw["config"].get(key) == Some(value), "native creation config differs");
126|        }
127|    }
128|    let native_uuid = raw["config"]["volatile.uuid"].as_str().context("native UUID absent")?.to_owned();
129|    ensure!(uuid::Uuid::parse_str(&native_uuid)?.to_string() == native_uuid, "noncanonical native UUID");
130|    let cozo = engine.identity_sled_store()?.cozo().clone();
131|    let pinned = record.clone();
132|    let bound = tokio::task::spawn_blocking(move || cozo.bind_native_creation(&pinned, &native_uuid)).await??;
133|    let snapshot = native.default_project_state().await?;
134|    let instance = snapshot.instances.iter().find(|i| i.name == bound.name)
135|        .context("created instance missing from full readback")?;
136|    ensure!(serde_json::to_value(instance)? == serde_json::to_value(incus::IncusPlugin::instance_from_native_metadata(raw)?)?,
137|        "native instance changed during full readback");
138|    crate::incus_observer::publish_repair_readback_locked(engine, &snapshot).await?;
139|    let cozo = engine.identity_sled_store()?.cozo().clone();
140|    Ok(tokio::task::spawn_blocking(move || cozo.complete_native_creation(&bound)).await??)
141|}
