143|pub(crate) async fn dispatch(engine: &MutationEngine, method: &str, args: &Value,
144|    actor: &str, session: Option<&str>, genesis: Option<&str>) -> Result<Value> {
145|    let session = session.context("native creation requires verified session")?.to_owned();
146|    let genesis = genesis.context("native creation requires verified genesis")?.to_owned();
147|    let engine = engine.clone();
148|    let method = method.to_owned();
149|    let args = args.clone();
150|    let actor = actor.to_owned();
151|    tokio::spawn(async move {
152|        let _host = engine.lock_host_observation().await;
153|        let (record, replayed) = if method == "create_instance" {
154|            let input: incus::CreateInstanceInput = serde_json::from_value(args)?;
155|            let body = incus::native_creation_body(&input)?;
156|            let request = request(&input.operation_id, &actor, &session, &genesis,
157|                "incus", &input.operation_id, body)?;
158|            create_locked(&engine, request).await?
159|        } else {
160|            let input: incus::ReconcileNativeCreationInput = serde_json::from_value(args)?;
161|            let record = records(&engine).await?.into_iter()
162|                .find(|r| r.request.operation_id == input.operation_id)
163|                .context("native creation operation not found")?;
164|            ensure!(record.request.owner_kind == "incus" && record.request.actor_id == actor
165|                && record.request.caller_session == session && record.request.caller_genesis == genesis,
166|                "native creation operation belongs to another owner");
167|            (reconcile_locked(&engine, record).await?, true)
168|        };
169|        Ok(json!({"name":record.name,"operation_id":record.request.operation_id,
170|            "native_uuid":record.native_uuid,"phase":record.phase,"replayed":replayed,
171|            "created":true,"changes":[]}))
172|    }).await.context("native creation owner failed; reconcile the same operation")?
